templates.body:
FROM {{var:index}}
| WHERE @timestamp > NOW() - {{var:range}}
| WHERE destination.ip {{op}} ({{iocs}}) OR source.ip {{op}} ({{iocs}})
| STATS events = COUNT(*), first_seen = MIN(@timestamp), last_seen = MAX(@timestamp)
        BY source.ip, destination.ip, destination.port, event.dataset
| SORT events DESC

FROM {{var:index}}
| WHERE @timestamp > NOW() - {{var:range}}
| WHERE {{field}} {{op}} ({{iocs}})
| KEEP @timestamp, host.name, source.ip, dns.question.name, dns.answers.data, dns.response_code
| SORT @timestamp DESC

FROM {{var:index}}
| WHERE @timestamp > NOW() - {{var:range}}
| WHERE {{field}} {{op}} ({{iocs}})
| KEEP @timestamp, source.ip, user.name, url.full, http.request.method, http.response.status_code, user_agent.original
| SORT @timestamp DESC

FROM {{var:index}}
| WHERE @timestamp > NOW() - {{var:range}}
| WHERE {{field}} {{op}} ({{iocs}}) OR process.hash.sha256 {{op}} ({{iocs}})
| KEEP @timestamp, host.name, user.name, event.action, file.path, process.name, process.command_line
| SORT @timestamp DESC
